export const SA_PROVINCES = ["Eastern Cape","Free State","Gauteng","KwaZulu-Natal","Limpopo","Mpumalanga","Northern Cape","North West","Western Cape"] as const;

export function placesForProvince(province: string): SouthAfricanPlace[] {
  return SA_PLACES.filter((place) => place.province === province);
}

export function findPlace(name: string, province?: string): SouthAfricanPlace | undefined {
  const key = name.trim().toLowerCase();
  return SA_PLACES.find(
    (place) =>
      place.name.toLowerCase() === key && (!province || place.province === province),
  );
}

export function nearestPlace(lat: number, lng: number): SouthAfricanPlace {
  let best = SA_PLACES[0];
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const place of SA_PLACES) {
    const dLat = ((place.lat - lat) * Math.PI) / 180;
    const dLng = ((place.lng - lng) * Math.PI) / 180;
    const a =
      Math.sin(dLat / 2) ** 2 +
      Math.cos((lat * Math.PI) / 180) *
        Math.cos((place.lat * Math.PI) / 180) *
        Math.sin(dLng / 2) ** 2;
    const distance = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    if (distance < bestDistance) {
      bestDistance = distance;
      best = place;
    }
  }
  return best;
}
